#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int v; struct Node *l, *r; } Node;
static Node *mk(int v) { Node *n = malloc(sizeof(Node)); n->v = v; n->l = n->r = NULL; return n; }

static void pre(Node *n)  { if (!n) return; printf(" %d", n->v); pre(n->l);  pre(n->r); }
static void ino(Node *n)  { if (!n) return; ino(n->l);  printf(" %d", n->v); ino(n->r); }
static void post(Node *n) { if (!n) return; post(n->l); post(n->r); printf(" %d", n->v); }

int main(void) {
    /*        A(1)
            /     \
          B(2)    C(3)
         /   \       \
       D(4)  E(5)    F(6)   —— 这里用 1..6 代替字母 */
    Node *a = mk(1), *b = mk(2), *c = mk(3), *d = mk(4), *e = mk(5), *f = mk(6);
    a->l = b; a->r = c; b->l = d; b->r = e; c->r = f;
    printf("前序:"); pre(a);  printf("\n");
    printf("中序:"); ino(a);  printf("\n");
    printf("后序:"); post(a); printf("\n");
    return 0;
}
